CREATE TABLE IF NOT EXISTS fact_inventory_snapshot (
    snapshot_date_key INTEGER,
    product_key INTEGER,
    store_key INTEGER,
    on_hand_qty INTEGER,
    units_sold_week INTEGER,
    reorder_point INTEGER,
    stockout_flag SMALLINT,
    inventory_value DECIMAL(14,2),
    PRIMARY KEY (snapshot_date_key, product_key, store_key),
    FOREIGN KEY (snapshot_date_key) REFERENCES dim_date(date_key),
